-- Generated 2026-10-11 from local WFO 2026-06 and NHM CSV exports.
-- Additive, idempotent data import: no schema changes; never modifies course plants/samples/images/fatty-acid rows.
-- All NHM-derived morphology/trait facts remain EXTRACTED or NEEDS_REVIEW and do not enter trait search.
-- Name fallback is accepted Latin name because sources contain no Chinese common name.
SET NAMES utf8mb4;
START TRANSACTION;





























































































































COMMIT;

SELECT 'plants_total' metric,COUNT(*) value FROM plants UNION ALL SELECT 'public_plants',COUNT(*) FROM plants WHERE is_public=1 UNION ALL SELECT 'nhm_wfo_plants',COUNT(*) FROM plants WHERE source_key LIKE 'nhm-wfo-%' UNION ALL SELECT 'nhm_trait_candidates',COUNT(*) FROM plant_trait_values WHERE source_key LIKE 'nhm-trait-%' UNION ALL SELECT 'nhm_confirmed_trait_values',COUNT(*) FROM plant_trait_values WHERE source_key LIKE 'nhm-trait-%' AND verification_status='CONFIRMED' UNION ALL SELECT 'nhm_raw_knowledge_entries',COUNT(*) FROM plant_knowledge_entries WHERE source_locator LIKE 'DOI 10.5519/%' UNION ALL SELECT 'wfo_taxonomy_refs',COUNT(*) FROM plant_taxonomy_references WHERE source_namespace='WFO' AND external_taxon_id LIKE 'wfo-%';
